import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";

export type Consent4 = {
  /**
   * A unique identifier that is used to identify and reference an instance of consent. It is
   * generated by Global Payments to identify the consent details used with this transaction
   */
  id?: string;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

export const consent4Schema: Schema<Consent4> = s.object<Consent4>(
  {
    id: s.optional(s.string()),
  },
  { additionalProperties: s.json() },
);
